<?php
declare(strict_types=1);
namespace App\Application\Performance\Service;
use App\Application\Performance\Port\TransactionManagerInterface;use App\Domain\Performance\Repository\AttemptRepositoryInterface;use App\Domain\QuestionLearning\Entity\LearningEvent;use App\Domain\QuestionLearning\Enum\LearningEventType;use App\Domain\QuestionLearning\Enum\LearningOutcome;use App\Domain\QuestionLearning\Repository\CompletedAttemptLearningSignalReaderInterface;use App\Domain\QuestionLearning\Repository\LearningEventRepositoryInterface;
final class CompleteAttemptService {public function __construct(private readonly AttemptRepositoryInterface $attempts,private readonly TransactionManagerInterface $transactions,private readonly ?CompletedAttemptLearningSignalReaderInterface $signalReader=null,private readonly ?LearningEventRepositoryInterface $events=null,private readonly \DateTimeZone $utc=new \DateTimeZone('UTC')){}public function complete(string $userId,string $attemptId):\DateTimeImmutable{return $this->transactions->transactional(function()use($userId,$attemptId){$attempt=$this->attempts->findByIdForUser($attemptId,$userId);if($attempt===null||$attempt->completedAt!==null)throw new \DomainException('Tentativa nao pode ser concluida.');$answers=$this->attempts->listAnswers($attemptId);if($answers===[])throw new \DomainException('Tentativa sem resposta.');$last=$answers[array_key_last($answers)];$at=new \DateTimeImmutable('now',$this->utc);if(!$this->attempts->complete($attemptId,$last->id,$at))throw new \DomainException('Tentativa nao pode ser concluida.');$signal=$this->signalReader?->read($attempt->questionId,(string)$last->optionId,$last->elapsedSeconds,$attempt->context);if($signal!==null&&$this->events!==null){$subjects=$signal->taxonomySubjectIds===[]?[null]:$signal->taxonomySubjectIds;foreach($subjects as $subjectId){$this->events->append(new LearningEvent($this->uuid(),$userId,$signal->questionId,$attemptId,$subjectId,LearningEventType::ANSWER_COMPLETED,$signal->correct?LearningOutcome::CORRECT:LearningOutcome::INCORRECT,$signal->elapsedSeconds,$signal->origin,['selected_option_id'=>$signal->selectedOptionId],$at));}}return $at;});}private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
